]







viewof shor_target = Inputs.select(SHOR_TARGETS, {
  label: "N to factor",
  format: t =&gt; `${t.N.toLocaleString()}  [${t.n}-bit]${t.n &gt;= 30 ? " 🖥️" : t.n &gt;= 28 ? " ☕" : t.n &gt;= 25 ? " ⏳" : ""}`
})







// WebGPU device + compiled H-gate pipeline — initialised once, reused across runs.
gpu_state = {
  if (typeof navigator === 'undefined' || !navigator.gpu) return null
  const adapter = await navigator.gpu.requestAdapter({ powerPreference: 'high-performance' })
  if (!adapter) return null
  let device
  try {
    device = await adapter.requestDevice({ requiredLimits: {
      maxBufferSize: adapter.limits.maxBufferSize,
      maxStorageBufferBindingSize: adapter.limits.maxStorageBufferBindingSize,
    }})
  } catch { return null }
  // H-gate compute shader: each thread processes one (i, j=i|bit) amplitude pair.
  const mod = device.createShaderModule({ code: `
    struct P { bit:u32, stride:u32, half:u32, _pad:u32 }
    @group(0) @binding(0) var&lt;storage,read_write&gt; re:array&lt;f32&gt;;
    @group(0) @binding(1) var&lt;storage,read_write&gt; im:array&lt;f32&gt;;
    @group(0) @binding(2) var&lt;uniform&gt; p:P;
    @compute @workgroup_size(256)
    fn main(@builtin(global_invocation_id) gid:vec3&lt;u32&gt;) {
      let idx = gid.x + gid.y * p.stride;
      if (idx &gt;= p.half) { return; }
      let lo = idx & (p.bit - 1u);
      let i  = lo | ((idx - lo) &lt;&lt; 1u);
      let j  = i  | p.bit;
      let s2 = 0.7071067811865476f;
      let r0=re[i]; let i0=im[i]; let r1=re[j]; let i1=im[j];
      re[i]=s2*(r0+r1); im[i]=s2*(i0+i1);
      re[j]=s2*(r0-r1); im[j]=s2*(i0-i1);
    }` })
  let pipeline
  try {
    pipeline = await device.createComputePipelineAsync({
      layout: 'auto', compute: { module: mod, entryPoint: 'main' }
    })
  } catch { device.destroy(); return null }
  return { device, pipeline, maxBuf: adapter.limits.maxBufferSize }
}







shor_holder = {
  const { N, a, aSq, n, t = 3 } = shor_target
  const total = t + n
  const size = 2 ** total

  // Use WebGPU when: t=1, GPU available, and each half-buffer fits in VRAM.
  // Split mode: when size*4 &gt; maxBuf, split re/im into two half-buffers of size/2 each.
  // Each half = size/2 × 4 bytes — same as n=29 single-buffer — so n=30 works wherever n=29 did.
  const gs = gpu_state
  const useGpu = t === 1 && gs != null && size * 2 &lt;= gs.maxBuf

  const holder = {}
  holder.promise = (async () =&gt; {
    let wakeLock = null
    if (n &gt;= 14 && navigator.wakeLock) {
      try { wakeLock = await navigator.wakeLock.request('screen') } catch (_) {}
    }
    await new Promise(r =&gt; setTimeout(r, 30))
    try {
      const t0 = performance.now()

      // n-bit reversal — used in both paths
      const bitrev = (x) =&gt; { let r=0,b=n; while(b--){r=(r&lt;&lt;1)|(x&1);x&gt;&gt;&gt;=1}; return r }

      // Period → factors: shared by GPU and CPU paths
      const gcd = (a, b) =&gt; { while (b) [a, b] = [b, a % b]; return a }
      const extractFactors = (countProbs) =&gt; {
        const periods = new Set()
        for (const [bits, p] of Object.entries(countProbs)) {
          if (p &lt; 0.05) continue
          const m = parseInt(bits, 2)
          if (m === 0) continue
          for (let r = 1; r &lt;= 2 * (1 &lt;&lt; t); r++)
            for (let s = 1; s &lt; r; s++)
              if (Math.abs(s / r - m / (1 &lt;&lt; t)) &lt; 0.5 / (1 &lt;&lt; t)) periods.add(r)
        }
        const factors = []
        for (const r of [...periods].sort((x, y) =&gt; x - y)) {
          if (r % 2 !== 0) continue
          const x = r === 4 ? aSq : r === 2 ? a : null
          if (!x || x === 1 || x === N - 1) continue
          const f1 = gcd(x - 1, N), f2 = gcd(x + 1, N)
          const fs = [f1, f2].filter(f =&gt; f &gt; 1 && f &lt; N)
          if (fs.length) factors.push({ r, p: fs[0], q: N / fs[0] })
        }
        return factors
      }

      if (useGpu) {
        // ── GPU path ───────────────────────────────────────────────────────────
        // Allocates re/im as Float32 in GPU VRAM — bypasses the browser tab heap limit.
        // Split mode: when a single size*4 buffer exceeds maxBuf, each component is split
        // into two half-buffers. H on qubit 0 (bit=1) never pairs indices across the split
        // boundary, so the same shader runs independently on each half.
        const { device, pipeline } = gs
        const BUF = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC
        const split = size * 4 &gt; gs.maxBuf
        const hlf   = size &gt;&gt;&gt; 1                        // half index (size always even here)
        const bufSz = (split ? hlf : size) * 4         // bytes per buffer
        const reBufs = [device.createBuffer({ size: bufSz, usage: BUF })]
        const imBufs = [device.createBuffer({ size: bufSz, usage: BUF })]
        if (split) {
          reBufs.push(device.createBuffer({ size: bufSz, usage: BUF }))
          imBufs.push(device.createBuffer({ size: bufSz, usage: BUF }))
        }

        // Write a single f32 to global index gi in the re component
        const writ = (bufs, gi, val) =&gt; {
          const k = split && gi &gt;= hlf ? 1 : 0
          device.queue.writeBuffer(bufs[k], (gi - k * hlf) * 4, new Float32Array([val]))
        }

        // Initialize work register to |1⟩: set re[bx] = 1
        // Use multiplication not &lt;&lt; to avoid 32-bit overflow when n≥31
        const bx = bitrev(1) * (2 ** t)
        writ(reBufs, bx, 1)

        // Dispatch H gate on qubit q using GPU compute shader.
        // In split mode, dispatch on each half independently — valid because bit=1 &lt; hlf,
        // so paired indices (i, i|bit) always fall within the same half.
        const WG = 256
        const dispatchH = (q) =&gt; {
          const bit  = 2 ** q
          const cnt  = split ? hlf : size   // elements per buffer
          const half = cnt / 2              // thread count per dispatch
          const numWg = Math.ceil(half / WG)
          const wx    = Math.min(numWg, 65535)
          const wy    = Math.ceil(numWg / wx)
          for (let k = 0; k &lt; reBufs.length; k++) {
            const uni = device.createBuffer({ size: 16,
              usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST })
            device.queue.writeBuffer(uni, 0, new Uint32Array([bit&gt;&gt;&gt;0, wx*WG, half&gt;&gt;&gt;0, 0]))
            const bg = device.createBindGroup({ layout: pipeline.getBindGroupLayout(0), entries: [
              { binding: 0, resource: { buffer: reBufs[k] } },
              { binding: 1, resource: { buffer: imBufs[k] } },
              { binding: 2, resource: { buffer: uni        } },
            ]})
            const enc = device.createCommandEncoder()
            const pass = enc.beginComputePass()
            pass.setPipeline(pipeline); pass.setBindGroup(0, bg)
            pass.dispatchWorkgroups(wx, wy); pass.end()
            device.queue.submit([enc.finish()])
            uni.destroy()
          }
        }

        // H(0): put counting qubit in superposition
        dispatchH(0)

        // Ctrl-mult(a, 0): state is exactly sparse — 2 non-zero entries at bx and bx+1.
        // Move the ctrl=1 entry from work=|1⟩ to work=|a⟩.
        // Use + not | to avoid 32-bit overflow when n≥31 (bx is always even)
        const src = bx + 1
        const wac = bitrev(a) * (2 ** t)
        const dst = wac + 1
        if (src !== dst) {
          await device.queue.onSubmittedWorkDone()
          writ(reBufs, src, 0)
          writ(reBufs, dst, Math.SQRT1_2)
        }

        // H(0) again: inverse QFT for t=1
        dispatchH(0)
        await device.queue.onSubmittedWorkDone()

        // Read back the 4 known non-zero indices to extract counting probabilities.
        // After the circuit: re[bx]=0.5, re[bx+1]=0.5, re[wac]=0.5, re[wac+1]=-0.5
        const idxs = [bx, bx + 1, wac, wac + 1]
        const stg  = device.createBuffer({ size: 16,
          usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST })
        const enc2 = device.createCommandEncoder()
        idxs.forEach((gi, k) =&gt; {
          const bufK = split && gi &gt;= hlf ? 1 : 0
          enc2.copyBufferToBuffer(reBufs[bufK], (gi - bufK * hlf) * 4, stg, k * 4, 4)
        })
        device.queue.submit([enc2.finish()])
        await stg.mapAsync(GPUMapMode.READ)
        const rv = Array.from(new Float32Array(stg.getMappedRange().slice(0)))
        stg.unmap(); stg.destroy()
        reBufs.forEach(b =&gt; b.destroy()); imBufs.forEach(b =&gt; b.destroy())

        // P(m=0) from indices 0,2 (bit0=0); P(m=1) from indices 1,3 (bit0=1)
        const P0 = rv[0]**2 + rv[2]**2
        const P1 = rv[1]**2 + rv[3]**2
        const countProbs = {}
        if (P0 &gt; 1e-6) countProbs['0'] = P0
        if (P1 &gt; 1e-6) countProbs['1'] = P1

        return { N, a, t, n, elapsed: performance.now()-t0, countProbs, factors: extractFactors(countProbs), gpu: true }
      }

      // ── CPU path ─────────────────────────────────────────────────────────────
      const re = new Float32Array(size)
      const im = new Float32Array(size)
      re[0] = 1

      // X on qubit (t+n-1) initialises work register to |1⟩
      const bx = 1 &lt;&lt; (t + n - 1)
      for (let i = 0; i &lt; size; i++) {
        if (i & bx) continue
        const j = i | bx
        const tr = re[i], ti = im[i]
        re[i] = re[j]; im[i] = im[j]
        re[j] = tr; im[j] = ti
      }

      const s2 = 1 / Math.sqrt(2)

      const applyH = (q) =&gt; {
        const bit = 1 &lt;&lt; q
        for (let i = 0; i &lt; size; i++) {
          if (i & bit) continue
          const j = i | bit
          const r0 = re[i], i0 = im[i], r1 = re[j], i1 = im[j]
          re[i] = s2 * (r0 + r1); im[i] = s2 * (i0 + i1)
          re[j] = s2 * (r0 - r1); im[j] = s2 * (i0 - i1)
        }
      }

      const applyPhase = (theta, ctrl, tgt) =&gt; {
        const cb = 1 &lt;&lt; ctrl, tb = 1 &lt;&lt; tgt
        const cos = Math.cos(theta), sin = Math.sin(theta)
        for (let i = 0; i &lt; size; i++) {
          if ((i & cb) && (i & tb)) {
            const r = re[i], im0 = im[i]
            re[i] = r * cos - im0 * sin
            im[i] = r * sin + im0 * cos
          }
        }
      }

      const applySwap = (qa, qb) =&gt; {
        const ba = 1 &lt;&lt; qa, bb = 1 &lt;&lt; qb
        for (let i = 0; i &lt; size; i++) {
          if ((i & ba) && !(i & bb)) {
            const j = (i & ~ba) | bb
            const tr = re[i], ti = im[i]
            re[i] = re[j]; im[i] = im[j]
            re[j] = tr; im[j] = ti
          }
        }
      }

      // Controlled-multiplication — in-place, no scratch arrays, no lookup table.
      // State is sparse (≤ 2^t non-zero amplitudes after H gates); collect them,
      // clear their positions, then scatter to the permuted work-register positions.
      const applyCtrlMult = (mul, ctrl_q) =&gt; {
        const cb = 1 &lt;&lt; ctrl_q
        const mask = (1 &lt;&lt; n) - 1
        const work_mask = mask &lt;&lt; t
        const hits = []
        for (let i = 0; i &lt; size; i++) {
          if ((i & cb) && (Math.abs(re[i]) &gt; 1e-15 || Math.abs(im[i]) &gt; 1e-15)) {
            hits.push(i, re[i], im[i])
            re[i] = 0; im[i] = 0
          }
        }
        for (let k = 0; k &lt; hits.length; k += 3) {
          const i = hits[k], r = hits[k+1], m = hits[k+2]
          const x = bitrev((i &gt;&gt; t) & mask)
          const y = x &lt; N ? (x * mul) % N : x
          const j = (i & ~work_mask) | (bitrev(y) &lt;&lt; t)
          re[j] += r; im[j] += m
        }
      }

      for (let i = 0; i &lt; t; i++) applyH(i)
      const aPows = [a, aSq, 1]
      for (let k = 0; k &lt; t; k++) {
        if (aPows[k] === 1) continue
        applyCtrlMult(aPows[k], k)
      }
      for (let i = 0; i &lt; Math.floor(t / 2); i++) applySwap(i, t - 1 - i)
      for (let j = 0; j &lt; t; j++) {
        for (let kk = j - 1; kk &gt;= 0; kk--) applyPhase(-Math.PI / 2 ** (j - kk), kk, j)
        applyH(j)
      }

      const countProbs = {}
      for (let i = 0; i &lt; size; i++) {
        const p = re[i] * re[i] + im[i] * im[i]
        if (p &lt; 1e-10) continue
        const m = (i &gt;&gt; n) & ((1 &lt;&lt; t) - 1)
        const key = m.toString(2).padStart(t, '0')
        countProbs[key] = (countProbs[key] || 0) + p
      }

      return { N, a, t, n, elapsed: performance.now() - t0, countProbs, factors: extractFactors(countProbs) }
    } finally {
      if (wakeLock) wakeLock.release()
    }
  })()
  return holder
}







{
  const holder = shor_holder
  const root = document.createElement('div')
  const spinner = document.createElement('div')
  spinner.className = 'shor-computing'
  spinner.innerHTML = '&lt;span class="shor-spinner"&gt;&lt;/span&gt; running QPE circuit\u2026'
  root.appendChild(spinner)

  holder.promise.then(({ N, a, t, n, elapsed, countProbs, factors, gpu }) =&gt; {
    spinner.remove()
    const maxP = Math.max(...Object.values(countProbs))
    const mem = (4 * 4 * (2 ** (t + n)) / 1e9).toFixed(1)
    const backend = gpu ? `GPU VRAM` : `~${mem} GB RAM`
    const lines = [
      `N = ${N}  (${n}-bit,  state space = 2^${t+n},  ${backend},  ${(elapsed/1000).toFixed(1)}s)`,
      `base a = ${a},  counting bits t = ${t}`,
      ``, `QPE counting register:`
    ]
    for (const [bits, p] of Object.entries(countProbs).sort((x, y) =&gt; parseInt(x[0], 2) - parseInt(y[0], 2))) {
      const m = parseInt(bits, 2)
      const bar = '\u2588'.repeat(Math.round(p / maxP * 24))
      lines.push(`  m=${String(m).padStart(2)}  \u03c6=${m}/${1 &lt;&lt; t}  ${(p * 100).toFixed(0).padStart(3)}%  ${bar}`)
    }
    lines.push(``)
    if (factors.length) {
      lines.push(`Period r = ${factors[0].r}`)
      lines.push(`${N} = ${factors[0].p} \xd7 ${factors[0].q}  \u2713`)
    } else {
      lines.push(`No factors found \u2014 try a different base`)
    }
    root.appendChild(pre(lines.join('\n')))
  }).catch(() =&gt; {
    spinner.remove()
    const msg = document.createElement('div')
    msg.style.cssText = 'color:#c0392b;font-size:0.85em;margin-top:4px'
    msg.textContent = '\u26a0 Simulation failed \u2014 browser ran out of memory. Try a smaller N.'
    root.appendChild(msg)
  })

  return root
}






The counting register peaks at multiples of 2^t / r. For r=2 with t=3 precision bits: peaks at m=0 and m=4. For r=4: peaks at m=0, 2, 4, 6. Continued fractions recovers r from any non-zero peak.

9.7 Simulating at scale with MPS
The chapters so far have used a statevector simulator: it stores all \(2^n\) amplitudes in memory and applies gates as matrix multiplications. For 30 qubits, that’s \(2^{30} \approx 10^9\) complex numbers — a few gigabytes. For 50 qubits it’s a petabyte. For 100 qubits, more memory than exists on Earth.
But many circuits of practical interest don’t actually need all of that. If a circuit has low entanglement, it has structure that can be exploited. The Matrix Product State (MPS) representation stores a chain of small tensors instead of one giant vector. The cost is controlled by a single number: \(\chi\), the bond dimension, which equals the maximum Schmidt rank across any bipartition of the qubits.
For a circuit with no entanglement, \(\chi = 1\). For a moderately entangled circuit, \(\chi\) might be 10 or 100. Only for highly entangled states does \(\chi\) grow to \(2^{n/2}\) — and only then does MPS hit the same wall as statevector.

9.7.1 A 1024-qubit circuit
A classical statevector simulator would need \(2^{1024}\) amplitudes to represent the following circuit. That number has about 300 digits — it dwarfs the number of atoms in the observable universe. No computer will ever store it.
Yet runMps returns in milliseconds:

result_1024 = {
  let c = new ket.Circuit(1024).h(0)
  for (let i = 0; i &lt; 1023; i++) c = c.cx(i, i+1)
  return c.runMps({ shots: 200 })
}







pre(`backend: ${result_1024.backend}   peakChi: ${result_1024.peakChi}   qubits: ${result_1024.qubits}`)






peakChi = 2. That’s why it’s fast. The GHZ circuit — H followed by a chain of CNOTs — produces a state with exactly two Schmidt values across every bipartition. Despite spanning 1024 qubits, the entanglement is as simple as a Bell state. MPS captures it in a chain of 2×2 tensors.
The outcome is only ever \(|00\ldots0\rangle\) or \(|11\ldots1\rangle\). Here’s what the histogram looks like on a smaller GHZ (8 qubits) where the bitstrings fit on screen:

ghz8_circ = {
  let c = new ket.Circuit(8).h(0)
  for (let i = 0; i &lt; 7; i++) c = c.cx(i, i+1)
  return c
}
svg(ghz8_circ.simulate({ shots: 500 }).toSVG())

















9.7.2 Entanglement entropy at scale
The bond entropies make this precise:

ghz8_circ.bondEntropies()






Every bond carries exactly 1 bit of entanglement entropy — the maximum for a two-outcome superposition. But \(\chi = 2\) is the minimum non-trivial bond dimension. The entanglement is wide (spread across every bond) but shallow (only two branches). MPS handles this efficiently because the tensor dimensions stay small.
Compare a product state:

{
  let prod = new ket.Circuit(8).h(0).h(1).h(2).h(3).h(4).h(5).h(6).h(7)
  return prod.bondEntropies()
}






All zeros. No gate connects any qubit to any other, so no entanglement crosses any bond. \(\chi = 1\) throughout.


9.7.3 When MPS is fast — and when it isn’t
The cost of MPS scales as \(O(n \chi^3)\) per gate layer. For low-entanglement circuits, \(\chi\) stays small regardless of \(n\), and the simulation is efficient. For high-entanglement circuits, \(\chi\) grows and eventually the simulation becomes as hard as statevector.

// Low entanglement: GHZ on 50 qubits — chi stays at 2
mps_ghz50 = {
  let c = new ket.Circuit(50).h(0)
  for (let i = 0; i &lt; 49; i++) c = c.cx(i, i+1)
  return c.runMps({ shots: 100 })
}







pre(`GHZ-50 — backend: ${mps_ghz50.backend}   peakChi: ${mps_ghz50.peakChi}`)







// Higher entanglement: brickwork circuit on 20 qubits — chi grows
mps_brick20 = {
  let c = new ket.Circuit(20)
  for (let layer = 0; layer &lt; 6; layer++) {
    for (let i = 0; i &lt; 19; i += 2) c = c.h(i).cx(i, i+1)
    for (let i = 1; i &lt; 18; i += 2) c = c.h(i).cx(i, i+1)
  }
  return c.runMps({ shots: 100, maxBond: 64 })
}







pre(`Brickwork-20 — backend: ${mps_brick20.backend}   peakChi: ${mps_brick20.peakChi}`)






The GHZ chain on 50 qubits has peakChi = 2 and runs instantly. The brickwork circuit — alternating layers of H and CX — builds up genuine entanglement and peakChi climbs. The maxBond parameter caps the bond dimension and introduces an approximation; without the cap, the simulation would be exact but exponentially slow.


9.7.4 MPS is not an approximation (for low-entanglement circuits)
This is the key point: when maxBond is not set, runMps is exact. For any circuit where \(\chi\) stays below a manageable threshold — GHZ states, many chemistry ansätze, QAOA at low depth, any circuit with a brickwork structure that doesn’t fully scramble — the MPS simulation gives the same result as a perfect statevector simulation.
The exponential difficulty of simulating quantum systems is not universal. It depends on the entanglement structure of the state. Circuits with low entanglement are efficiently simulable classically — and that’s not a bug, it’s a feature: it tells you exactly how much quantum advantage a given circuit has.
When \(\chi\) grows exponentially, you’ve found a circuit that is genuinely hard to simulate classically. That’s the regime where quantum hardware offers real advantage — and where MPS, too, runs out of room.

11.1 Clifford circuits at scale
The same .simulate() call handles circuits ranging from 2 qubits to 1000+. It does this by routing to different backends depending on what the circuit contains:
The routing is automatic. You don’t select a backend — simulate() inspects the circuit and picks the right one.
A Clifford circuit uses only stabilizer gates: H, S, X, Y, Z, CNOT, CZ, SWAP, and measurement. The Gottesman–Knill theorem says these circuits are classically simulable in polynomial time using a stabilizer tableau — a compact \(O(n^2)\) representation that never touches the exponential state space.
// 1000-qubit circuit — every qubit put in superposition
clifford_1000 = {
  let c = new ket.Circuit(1000)
  for (let i = 0; i &lt; 1000; i++) c = c.h(i)
  return c.simulate({ shots: 200 })
}
pre(`backend: ${clifford_1000.backend}   qubits: ${clifford_1000.qubits}`)
A 1000-qubit statevector would need \(2^{1000}\) amplitudes — a number with 300 digits. The Clifford backend handles it by never constructing that vector at all.
The price: Clifford circuits can’t produce arbitrary quantum states. The Clifford group is exactly the set of circuits that don’t require exponential classical resources to simulate. This is why random Clifford circuits don’t give quantum advantage — they sit inside the simulable region. Quantum speedup requires gates that escape it (like T, Toffoli, and the gates inside Shor’s controlled-\(U_a\)).
Here’s the same 1000-qubit structure but with a CNOT chain, which is still Clifford:
clifford_ghz = {
  let c = new ket.Circuit(1000).h(0)
  for (let i = 0; i &lt; 999; i++) c = c.cx(i, i+1)
  return c.simulate({ shots: 200 })
}
pre(`backend: ${clifford_ghz.backend}   qubits: ${clifford_ghz.qubits}`)
Only \(|00\ldots0\rangle\) and \(|11\ldots1\rangle\) — a 1000-qubit GHZ state, simulated classically in seconds.
